// Parse and orchestrate Code Fabric request
const request = $input.first().json;

// Required fields validation
if (!request.character_request) {
  return [{
    json: {
      error: 'Missing required field: character_request',
      status: 'invalid_request',
      message: 'Please provide your character request in the character_request field'
    }
  }];
}

// Create orchestration context
const context = {
  session_id: generateSessionId(),
  timestamp: new Date().toISOString(),
  character_request: request.character_request,
  character_profile: {
    character_id: request.character_id || 'character_' + Date.now(),
    character_class: request.character_class || 'unknown',
    character_level: request.character_level || 1,
    party_composition: request.party_composition || [],
    current_situation: request.current_situation || 'unknown',
    play_style: request.play_style || 'balanced',
    preferences: request.preferences || {}
  },
  orchestration_config: {
    processing_mode: request.processing_mode || 'comprehensive',
    include_learning: request.include_learning !== false,
    include_pattern_matching: request.include_pattern_matching !== false,
    generate_complete_solution: request.generate_complete_solution !== false,
    provide_explanations: request.provide_explanations !== false,
    enable_feedback_loop: request.enable_feedback_loop !== false
  },
  workflow_state: {
    current_phase: 'initialization',
    completed_phases: [],
    active_components: [],
    data_flow: {},
    errors: [],
    metrics: {
      processing_start_time: Date.now(),
      phase_timings: {},
      component_timings: {}
    }
  }
};

function generateSessionId() {
  return 'cf_session_' + Date.now() + '_' + Math.random().toString(36).substr(2, 8);
}

return [{
  json: context
}];

// Initialize orchestration workflow and determine processing path
const context = $input.first().json;

// Analyze request complexity and determine processing strategy
const requestAnalysis = {
  complexity_level: determineComplexityLevel(context.character_request),
  processing_phases: determineProcessingPhases(context),
  component_sequence: determineComponentSequence(context),
  estimated_processing_time: estimateProcessingTime(context),
  resource_requirements: calculateResourceRequirements(context)
};

function determineComplexityLevel(request) {
  const requestText = (request.character_request || '').toLowerCase();
  let complexity = 1;

  // Base complexity factors
  if (requestText.length > 100) complexity += 1;
  if (requestText.includes('protect') || requestText.includes('heal')) complexity += 1;
  if (requestText.includes('party') || requestText.includes('team')) complexity += 1;
  if (requestText.includes('automatic') || requestText.includes('automation')) complexity += 2;

  // Class-specific complexity
  if (request.character_class === 'wizard' || request.character_class === 'cleric') complexity += 1;
  if (request.character_level > 10) complexity += 1;

  if (complexity <= 2) return 'simple';
  if (complexity <= 4) return 'medium';
  if (complexity <= 6) return 'complex';
  return 'enterprise';
}

function determineProcessingPhases(context) {
  const phases = ['semantic_understanding'];

  if (context.orchestration_config.include_pattern_matching) {
    phases.push('pattern_recognition');
  }

  phases.push('business_logic_interpretation');

  if (context.orchestration_config.include_learning) {
    phases.push('codebase_intelligence');
  }

  if (context.orchestration_config.generate_complete_solution) {
    phases.push('solution_architecture');
  }

  phases.push('response_generation');

  return phases;
}

function determineComponentSequence(context) {
  return [
    {
      component: 'semantic_understanding_engine',
      phase: 'semantic_understanding',
      dependencies: [],
      critical_path: true
    },
    {
      component: 'pattern_recognition_library',
      phase: 'pattern_recognition',
      dependencies: ['semantic_understanding'],
      critical_path: context.orchestration_config.include_pattern_matching
    },
    {
      component: 'business_logic_interpreter',
      phase: 'business_logic_interpretation',
      dependencies: ['semantic_understanding'],
      critical_path: true
    },
    {
      component: 'codebase_intelligence_system',
      phase: 'codebase_intelligence',
      dependencies: ['semantic_understanding', 'pattern_recognition'],
      critical_path: context.orchestration_config.include_learning
    },
    {
      component: 'solution_architecture_generator',
      phase: 'solution_architecture',
      dependencies: ['business_logic_interpretation', 'pattern_recognition'],
      critical_path: context.orchestration_config.generate_complete_solution
    }
  ].filter(comp => comp.critical_path !== false);
}

function estimateProcessingTime(context) {
  const baseTime = 5; // Base 5 seconds
  const complexityMultipliers = {
    simple: 1.0,
    medium: 1.5,
    complex: 2.0,
    enterprise: 3.0
  };

  const phaseMultipliers = {
    semantic_understanding: 1.0,
    pattern_recognition: 0.8,
    business_logic_interpretation: 1.2,
    codebase_intelligence: 0.6,
    solution_architecture: 1.5
  };

  const phases = determineProcessingPhases(context);
  const totalMultiplier = phases.reduce((sum, phase) => 
    sum + (phaseMultipliers[phase] || 1.0), 0
  ) / phases.length;

  return Math.ceil(baseTime * complexityMultipliers[requestAnalysis.complexity_level] * totalMultiplier);
}

function calculateResourceRequirements(context) {
  return {
    ai_tokens_estimate: estimateTokens(context),
    processing_memory: requestAnalysis.complexity_level === 'enterprise' ? 'high' : 'medium',
    integration_calls: determineProcessingPhases(context).length,
    concurrent_processing: requestAnalysis.complexity_level === 'simple' ? false : true
  };
}

function estimateTokens(context) {
  const baseTokens = 1000;
  const requestTokens = context.character_request.length * 2;
  const complexityTokens = {
    simple: 500,
    medium: 1000,
    complex: 2000,
    enterprise: 3000
  };

  return baseTokens + requestTokens + complexityTokens[requestAnalysis.complexity_level];
}

return [{
  json: {
    ...context,
    request_analysis: requestAnalysis,
    orchestration_plan: {
      total_phases: requestAnalysis.processing_phases.length,
      estimated_duration: requestAnalysis.estimated_processing_time,
      component_sequence: requestAnalysis.component_sequence,
      parallel_execution: requestAnalysis.complexity_level !== 'simple'
    },
    current_phase: 'semantic_understanding',
    phase_start_time: Date.now()
  }
}];

// Phase 1: Semantic Understanding
const context = $input.first().json;

const semanticRequest = {
  character_input: context.character_request,
  character_class: context.character_profile.character_class,
  character_level: context.character_profile.character_level,
  party_composition: context.character_profile.party_composition,
  current_quest: context.character_profile.current_situation,
  play_style: context.character_profile.play_style,
  analysis_depth: context.orchestration_config.processing_mode,
  include_code_generation: context.orchestration_config.generate_complete_solution,
  include_explanations: context.orchestration_config.provide_explanations,
  learning_mode: 'adaptive',
  session_id: context.session_id,
  character_id: context.character_profile.character_id
};

return [{
  json: {
    ...context,
    phase: 'semantic_understanding',
    phase_start_time: Date.now(),
    semantic_request: semanticRequest,
    next_phase: context.orchestration_config.include_pattern_matching ? 'pattern_recognition' : 'business_logic_interpretation'
  }
}];

// Process semantic understanding results
const response = $input.first().json;
const originalContext = items.find(item => item.json.phase === 'semantic_understanding')?.json;

const phaseResult = {
  phase: 'semantic_understanding',
  status: response.status || 'unknown',
  start_time: originalContext.phase_start_time,
  end_time: Date.now(),
  duration: Date.now() - originalContext.phase_start_time,
  result: response,
  success: response.status === 'success'
};

return [{
  json: {
    ...originalContext,
    workflow_state: {
      ...originalContext.workflow_state,
      completed_phases: [...originalContext.workflow_state.completed_phases, 'semantic_understanding'],
      current_phase: originalContext.next_phase,
      metrics: {
        ...originalContext.workflow_state.metrics,
        phase_timings: {
          ...originalContext.workflow_state.metrics.phase_timings,
          semantic_understanding: phaseResult.duration
        }
      }
    },
    phase_results: {
      ...originalContext.phase_results || {},
      semantic_understanding: phaseResult
    },
    semantic_understanding_result: response,
    character_intent_understood: response.character_intent_understood || 'Intent analysis failed'
  }
}];

// Phase 2: Pattern Recognition (if enabled)
const context = $input.first().json;

if (!context.orchestration_config.include_pattern_matching) {
  return [{
    json: {
      ...context,
      workflow_state: {
        ...context.workflow_state,
        current_phase: 'business_logic_interpretation'
      },
      phase: 'pattern_recognition',
      status: 'skipped',
      reason: 'Pattern matching disabled in configuration'
    }
  }];
}

const patternRequest = {
  operation_type: 'identify_patterns',
  character_id: context.character_profile.character_id,
  session_id: context.session_id,
  input_data: {
    scenario_description: context.character_request,
    character_class: context.character_profile.character_class,
    character_level: context.character_profile.character_level,
    party_composition: context.character_profile.party_composition,
    objectives: [context.semantic_understanding_result?.business_goal || 'Achieve character goal'],
    urgency_level: 'normal'
  },
  search_scope: 'all_characters',
  time_period: 'last_30_days',
  success_threshold: 0.7,
  include_explanations: context.orchestration_config.provide_explanations,
  confidence_threshold: 0.6
};

return [{
  json: {
    ...context,
    phase: 'pattern_recognition',
    phase_start_time: Date.now(),
    pattern_request: patternRequest,
    next_phase: 'business_logic_interpretation'
  }
}];

// Process pattern recognition results
const response = $input.first().json;
const originalContext = items.find(item => item.json.phase === 'pattern_recognition')?.json;

const phaseResult = {
  phase: 'pattern_recognition',
  status: response.status || 'unknown',
  start_time: originalContext.phase_start_time,
  end_time: Date.now(),
  duration: Date.now() - originalContext.phase_start_time,
  result: response,
  success: response.status === 'success'
};

return [{
  json: {
    ...originalContext,
    workflow_state: {
      ...originalContext.workflow_state,
      completed_phases: [...originalContext.workflow_state.completed_phases, 'pattern_recognition'],
      current_phase: originalContext.next_phase,
      metrics: {
        ...originalContext.workflow_state.metrics,
        phase_timings: {
          ...originalContext.workflow_state.metrics.phase_timings,
          pattern_recognition: phaseResult.duration
        }
      }
    },
    phase_results: {
      ...originalContext.phase_results || {},
      pattern_recognition: phaseResult
    },
    pattern_recognition_result: response,
    identified_patterns: response.pattern_analysis?.patterns_identified || 0
  }
}];

// Phase 3: Business Logic Interpretation
const context = $input.first().json;

const businessRequest = {
  character_goal: context.character_request,
  character_context: {
    class: context.character_profile.character_class,
    level: context.character_profile.character_level,
    party_role: context.character_profile.party_composition.length > 0 ? 'leader' : 'member',
    play_style: context.character_profile.play_style,
    current_situation: context.character_profile.current_situation,
    available_resources: context.character_profile.preferences || {},
    constraints: [],
    preferences: context.character_profile.preferences
  },
  urgency_level: 'normal',
  complexity_tolerance: 'medium',
  automation_preference: 'balanced',
  success_metrics: ['effectiveness', 'reliability'],
  stakeholder_analysis: {
    primary: 'character',
    secondary: ['party', 'dm']
  },
  analysis_depth: context.orchestration_config.processing_mode
};

return [{
  json: {
    ...context,
    phase: 'business_logic_interpretation',
    phase_start_time: Date.now(),
    business_request: businessRequest,
    next_phase: context.orchestration_config.include_learning ? 'codebase_intelligence' : 'solution_architecture'
  }
}];

// Process business logic interpretation results
const response = $input.first().json;
const originalContext = items.find(item => item.json.phase === 'business_logic_interpretation')?.json;

const phaseResult = {
  phase: 'business_logic_interpretation',
  status: response.status || 'unknown',
  start_time: originalContext.phase_start_time,
  end_time: Date.now(),
  duration: Date.now() - originalContext.phase_start_time,
  result: response,
  success: response.status === 'success'
};

return [{
  json: {
    ...originalContext,
    workflow_state: {
      ...originalContext.workflow_state,
      completed_phases: [...originalContext.workflow_state.completed_phases, 'business_logic_interpretation'],
      current_phase: originalContext.next_phase,
      metrics: {
        ...originalContext.workflow_state.metrics,
        phase_timings: {
          ...originalContext.workflow_state.metrics.phase_timings,
          business_logic_interpretation: phaseResult.duration
        }
      }
    },
    phase_results: {
      ...originalContext.phase_results || {},
      business_logic_interpretation: phaseResult
    },
    business_logic_result: response,
    business_strategy_defined: response.strategic_analysis?.problem_statement ? true : false
  }
}];

>// Final orchestration response preparation
const context = $input.first().json;

// Calculate overall metrics
const totalProcessingTime = Date.now() - context.workflow_state.metrics.processing_start_time;
const successfulPhases = context.workflow_state.completed_phases.filter(phase => 
  context.phase_results?.[phase]?.success
).length;
const totalPhases = context.request_analysis.processing_phases.length;

// Generate comprehensive response
const orchestrationResponse = {
  status: successfulPhases === totalPhases ? 'success' : 'partial_success',
  session_id: context.session_id,
  character_id: context.character_profile.character_id,
  timestamp: new Date().toISOString(),
  processing_summary: {
    total_phases: totalPhases,
    completed_phases: successfulPhases,
    total_processing_time: totalProcessingTime,
    complexity_level: context.request_analysis.complexity_level,
    orchestration_mode: context.orchestration_config.processing_mode
  },
  character_understanding: {
    original_request: context.character_request,
    interpreted_intent: context.semantic_understanding_result?.character_intent_understood || 'Intent unclear',
    business_goal: context.semantic_understanding_result?.business_goal || 'Goal identification failed',
    automation_type: context.semantic_understanding_result?.automation_type || 'general'
  },
  solution_components: {
    semantic_analysis: context.semantic_understanding_result || null,
    pattern_matches: context.pattern_recognition_result || null,
    business_strategy: context.business_logic_result || null,
    solution_architecture: null // Will be populated if solution generation was triggered
  },
  recommendations: {
    immediate_actions: generateImmediateActions(context),
    implementation_suggestions: generateImplementationSuggestions(context),
    learning_opportunities: generateLearningOpportunities(context),
    customization_options: generateCustomizationOptions(context)
  },
  character_friendly_summary: generateCharacterFriendlySummary(context),
  next_steps: generateNextSteps(context),
  quality_metrics: {
    confidence_score: calculateOverallConfidence(context),
    completeness_score: (successfulPhases / totalPhases) * 100,
    accuracy_estimate: estimateAccuracy(context),
    user_satisfaction_prediction: predictUserSatisfaction(context)
  },
  metadata: {
    tokens_used_estimate: context.request_analysis.resource_requirements.ai_tokens_estimate,
    components_executed: context.orchestration_plan.component_sequence.length,
    errors_encountered: context.workflow_state.errors.length,
    learning_enabled: context.orchestration_config.include_learning,
    pattern_matching_enabled: context.orchestration_config.include_pattern_matching
  }
};

function generateImmediateActions(context) {
  const actions = [];

  if (context.semantic_understanding_result?.next_actions) {
    actions.push(...context.semantic_understanding_result.next_actions);
  }

  if (context.pattern_recognition_result?.pattern_recommendations) {
    actions.push('Review identified patterns for applicability');
  }

  if (context.business_logic_result?.next_actions) {
    actions.push(...context.business_logic_result.next_actions);
  }

  return actions.slice(0, 5); // Limit to 5 most important actions
}

function generateImplementationSuggestions(context) {
  const suggestions = [];

  if (context.semantic_understanding_result?.automation_type) {
    suggestions.push(`Implement ${context.semantic_understanding_result.automation_type} automation system`);
  }

  if (context.pattern_recognition_result?.implementation_readiness?.ready_to_implement) {
    suggestions.push('Begin implementation of recommended patterns');
  }

  if (context.business_logic_result?.technical_roadmap) {
    suggestions.push('Follow the technical roadmap for implementation');
  }

  return suggestions;
}

function generateLearningOpportunities(context) {
  const opportunities = [];

  if (context.pattern_recognition_result?.learning_insights?.success_factors) {
    opportunities.push('Learn from identified success factors');
  }

  if (context.business_logic_result?.implementation_readiness?.risk_assessment) {
    opportunities.push('Study risk assessment for future improvements');
  }

  opportunities.push('Monitor system performance and user feedback');

  return opportunities;
}

function generateCustomizationOptions(context) {
  return [
    'Adjust automation sensitivity and responsiveness',
    'Customize notification preferences',
    'Modify success criteria and thresholds',
    'Personalize interaction style and language'
  ];
}

function generateCharacterFriendlySummary(context) {
  const intent = context.semantic_understanding_result?.character_intent_understood || 'your request';
  const automationType = context.semantic_understanding_result?.automation_type || 'assistance';
  const complexity = context.request_analysis.complexity_level;

  return {
    what_i_understand: `You want to ${intent.toLowerCase()}`,
    what_i_can_do: `I can create a ${automationType} system to help you achieve this goal`,
    how_complex: `This is a ${complexity} solution that will require some setup`,
    what_to_expect: 'The system will monitor your situation and automatically help when needed',
    your_control: 'You can customize settings and override automation at any time'
  };
}

function generateNextSteps(context) {
  const steps = [
    'Review the understanding and recommendations provided',
    'Decide on the level of automation you want',
    'Begin implementation based on your preferences'
  ];

  if (context.orchestration_config.enable_feedback_loop) {
    steps.push('Provide feedback to help improve future recommendations');
  }

  return steps;
}

function calculateOverallConfidence(context) {
  let confidence = 70; // Base confidence

  if (context.semantic_understanding_result?.status === 'success') confidence += 15;
  if (context.pattern_recognition_result?.status === 'success') confidence += 10;
  if (context.business_logic_result?.status === 'success') confidence += 15;

  // Adjust based on complexity
  if (context.request_analysis.complexity_level === 'simple') confidence += 5;
  if (context.request_analysis.complexity_level === 'enterprise') confidence -= 10;

  return Math.min(confidence, 95);
}

function estimateAccuracy(context) {
  const successfulPhases = context.workflow_state.completed_phases.filter(phase => 
    context.phase_results?.[phase]?.success
  ).length;
  return Math.round((successfulPhases / context.request_analysis.processing_phases.length) * 100);
}

function predictUserSatisfaction(context) {
  const accuracy = estimateAccuracy(context);
  const confidence = calculateOverallConfidence(context);
  const complexity = context.request_analysis.complexity_level;

  let satisfaction = (accuracy + confidence) / 2;

  if (complexity === 'simple') satisfaction += 10;
  if (complexity === 'enterprise') satisfaction -= 15;

  if (context.orchestration_config.provide_explanations) satisfaction += 5;

  return Math.min(Math.round(satisfaction), 95);
}

return [{
  json: orchestrationResponse
}];

// Error handling for orchestration
const error = $input.first().json;

const errorResponse = {
  status: 'error',
  timestamp: new Date().toISOString(),
  session_id: error.session_id || 'unknown',
  character_id: error.character_id || 'unknown',
  error: error.error || 'Orchestration failed',
  details: error.details || 'No additional details available',
  phase_failed: error.phase || 'unknown',
  suggestions: [
    'Check your request format and try again',
    'Ensure all required fields are provided',
    'Try with a simpler request if the problem persists',
    'Contact support if the issue continues'
  ],
  partial_results: error.phase_results || {},
  recovery_options: [
    'Retry the orchestration',
    'Request a simpler analysis',
    'Proceed with manual implementation'
  ]
};

return [{
  json: errorResponse
}];
